value.program:
reads = state["reads"]
params = state["parameters"]
contacts = reads["people"]
if params["groups"] > 1:
    contacts = [row for group in contacts for row in group]
identities = set()
for person in contacts:
    email = person.get("email")
    if not isinstance(email, str) or not email.strip():
        return None
    identities.add(email.strip().casefold())
selected = {}
for port, actor in params["actors"].items():
    for row in reads[port]:
        person = row.get(actor, {})
        email = person.get("email") if isinstance(person, dict) else None
        if not isinstance(email, str) or not email.strip():
            return None
        if params["start"]:
            created = row.get("created_at")
            if not isinstance(created, str):
                return None
            if created[:10] < params["start"] or created[:10] > params["end"]:
                continue
        if email.strip().casefold() in identities:
            selected[row[params["id"]]] = row
return list(selected.values())

dynamic.plan:
goal = state["goal"]
if not regex(r"\bvenmo\b", goal) or regex(r"\bsocial feed\b", goal):
    return []
if state["answer_question"] and not regex(r"\bhow (?:much|many)\b", goal):
    return []
aliases = {"friend":"friends?", "coworker":"co[- ]?workers?|colleagues?", "roommate":"roommates?|housemates?", "sibling":"siblings?", "manager":"managers?"}
people = [group for group, alias in aliases.items() if regex(r"\b(?:" + alias + r")\b", goal)]
if not people or regex(r"\b(?:except|excluding|unless)\b", goal):
    return []
windows = calendar_windows(goal, state["datetime"])
if not windows:
    return []
pending = regex(r"\bpending\b", goal) and regex(r"\bpayment requests?\b", goal)
received = regex(r"\breceived\b", goal)
sent = regex(r"\bsent\b", goal)
directions = [["received"]]
if pending:
    directions = [["pending"]]
elif received and sent:
    directions = [["received", "sent"]]
    if regex(r"\bor\b", goal):
        directions.extend([["received"], ["sent"]])
elif sent:
    directions = [["sent"]]
elif not received and state["answer_question"]:
    return []
plans = []
for direction in directions:
    for start, end in windows:
        actors = {}
        choices = {"records": " and ".join(direction), "contacts": ", ".join(people)}
        if start:
            choices["date"] = start + " through " + end + " inclusive"
        reads = {"people": {"source": "phone__search_contacts", "arguments": [{"relationship": g} for g in people]}}
        for source in direction:
            if source == "pending":
                reads[source] = {"source": "venmo__show_received_payment_requests", "arguments": [{"status": "pending"}]}
            else:
                args = {"direction": source}
                if start:
                    args["min_created_at"] = start
                reads[source] = {"source": "venmo__show_transactions", "arguments": [args]}
            actors[source] = "receiver" if source == "sent" else "sender"
        result = "requests" if pending else "payments"
        plans.append({"result": result, "choices": choices, "reads": reads, "parameters": {
            "actors": actors, "id": "payment_request_id" if pending else "transaction_id",
            "groups": len(people), "start": start, "end": end}})
return plans
